NCU=/usr/local/cuda/bin/ncu
echo "=== Extract per-launch: ID(1), KernelName(5), Block(8), Grid(9), Duration avg(344) ==="
$NCU -i "$FILE" --csv --page raw 2>/dev/null | awk -F'","' '
NR==1 {next}
{
  id=$1; gsub(/"/,"",id);
  name=$5;
  block=$8;
  grid=$9;
  dur=$344;
  printf "ID=%s | %s | block=%s grid=%s | dur(ns)=%s\n", id, name, block, grid, dur
}'
